/**
 * Generic plugin hook runner (HKS-001)
 * Fail-closed for before hooks, fail-open for after hooks.
 */

import type { DatafnPlugin, DatafnHookContext } from "./types.js";

export interface HookError {
  code: string;
  message: string;
  details?: Record<string, unknown>;
}

export type BeforeHookResult<T> =
  | { ok: true; value: T }
  | { ok: false; error: HookError };

type AfterHookName = "afterQuery" | "afterMutation" | "afterSync";

function wrapError(err: unknown, pluginName: string, hookName: string): HookError {
  if (err && typeof err === "object") {
    const e = err as Record<string, unknown>;
    return {
      code: (e.code as string) || "INTERNAL",
      message: (e.message as string) || "Plugin error",
      details: { path: `plugins.${pluginName}.${hookName}`, ...((e.details as Record<string, unknown>) ?? {}) },
    };
  }
  return {
    code: "INTERNAL",
    message: String(err),
    details: { path: `plugins.${pluginName}.${hookName}` },
  };
}

/**
 * Run a before-style hook across plugins filtered by env.
 * Fail-closed: first error stops the chain and returns { ok: false, error }.
 * Each hook's return value (if defined) becomes the new payload.
 *
 * @param preArgs Optional args inserted before payload in hook call: hook(ctx, ...preArgs, payload)
 */
export async function runBeforeHook<T = unknown>(
  plugins: DatafnPlugin[],
  env: "client" | "server",
  hookName: keyof DatafnPlugin,
  ctx: DatafnHookContext,
  payload: T,
  preArgs: unknown[] = [],
): Promise<BeforeHookResult<T>> {
  let current = payload;
  const filtered = plugins.filter((p) => p.runsOn.includes(env));

  for (const plugin of filtered) {
    const hook = plugin[hookName] as ((...args: unknown[]) => Promise<unknown> | unknown) | undefined;
    if (!hook) continue;

    try {
      const result = await hook(ctx, ...preArgs, current);
      if (result !== undefined) current = result as T;
    } catch (err) {
      return { ok: false, error: wrapError(err, plugin.name, String(hookName)) };
    }
  }

  return { ok: true, value: current };
}

/**
 * Run an after-style hook across plugins filtered by env.
 * Fail-open: errors are logged but do not stop the chain.
 *
 * @param preArgs Optional args inserted before payload in hook call: hook(ctx, ...preArgs, payload, result)
 */
export async function runAfterHook(
  plugins: DatafnPlugin[],
  env: "client" | "server",
  hookName: AfterHookName,
  ctx: DatafnHookContext,
  payload: unknown,
  result: unknown,
  preArgs: unknown[] = [],
): Promise<unknown> {
  const filtered = plugins.filter((p) => p.runsOn.includes(env));
  let currentResult = result;

  for (const plugin of filtered) {
    const hook = plugin[hookName] as ((...args: unknown[]) => Promise<unknown> | unknown) | undefined;
    if (!hook) continue;

    try {
      const nextResult = await hook(ctx, ...preArgs, payload, currentResult);
      if (nextResult !== undefined) {
        currentResult = nextResult;
      }
    } catch (err) {
      console.error(`Plugin ${plugin.name}.${String(hookName)} error:`, err);
    }
  }

  return currentResult;
}

import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

export const repoRoot = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..", "..");

export const docsProducts = {
  datafn: {
    packageName: "@datafn/docs",
    docsDir: "datafn/docs",
    kind: "next-static",
    zoneName: "datafn.dev",
    hosts: {
      dev: "dev.datafn.dev",
      live: "datafn.dev",
    },
    routeAliases: {
      live: ["www.datafn.dev"],
    },
  },
  filefn: {
    packageName: "@filefn/docs",
    docsDir: "filefn/docs",
    kind: "sveltekit-cloudflare",
    zoneName: "filefn.com",
    hosts: {
      dev: "dev.filefn.com",
      live: "filefn.com",
    },
  },
  searchfn: {
    packageName: "@searchfn/docs",
    docsDir: "searchfn/docs",
    kind: "next-static",
    zoneName: "searchfn.com",
    hosts: {
      dev: "dev.searchfn.com",
      live: "searchfn.com",
    },
    routeAliases: {
      live: ["www.searchfn.com"],
    },
  },
  authfn: {
    packageName: "@authfn/docs",
    docsDir: "authfn/docs",
    kind: "sveltekit-cloudflare",
    zoneName: "authfn.com",
    hosts: {
      dev: "dev.authfn.com",
      live: "authfn.com",
    },
  },
};

export const environments = ["dev", "live"];

export function normalizeEnvironment(value) {
  const normalized = String(value ?? "").trim().toLowerCase();
  return environments.includes(normalized) ? normalized : null;
}

export function productIds() {
  return Object.keys(docsProducts);
}

export function existingProductIds() {
  return productIds().filter((productId) => hasDocsPackage(productId));
}

export function parseProducts(value, { existingOnly = false } = {}) {
  const raw = String(value ?? "all").trim();
  const available = existingOnly ? existingProductIds() : productIds();
  if (raw === "all") return available;

  const selected = raw.split(",").map((entry) => entry.trim()).filter(Boolean);
  if (selected.length === 0) {
    throw new Error("At least one docs product is required.");
  }

  for (const productId of selected) {
    if (!docsProducts[productId]) {
      throw new Error(`Invalid docs product: ${productId}`);
    }
    if (existingOnly && !hasDocsPackage(productId)) {
      throw new Error(`Docs package is missing for ${productId}: ${docsProducts[productId].docsDir}/package.json`);
    }
  }

  return [...new Set(selected)];
}

export function hasDocsPackage(productId) {
  return fs.existsSync(path.join(repoRoot, docsProducts[productId].docsDir, "package.json"));
}

export function workerName(productId, environment) {
  return `superfunctions-${productId}-docs-${environment}`;
}

export function routeDefinition(productId, environment) {
  const product = docsProducts[productId];
  return {
    product: productId,
    zoneName: product.zoneName,
    pattern: `${product.hosts[environment]}/docs*`,
    script: workerName(productId, environment),
  };
}

export function routesFor(environment, products) {
  return products.flatMap((productId) => {
    const route = routeDefinition(productId, environment);
    const product = docsProducts[productId];
    const aliases = product.routeAliases?.[environment] ?? [];
    return [
      route,
      ...aliases.map((host) => ({
        ...route,
        pattern: `${host}/docs*`,
      })),
    ];
  });
}

export function jsonArray(values) {
  return JSON.stringify([...new Set(values)]);
}

